(10, 1, 6, 4, 'lost', 'active', 'Zelený deštník', 'zeleny-destnik', 'Skládací zelený deštník v obalu. Nechaný u stojanu na chodbě.', 'zeleny destnik skladaci zeleny destnik v obalu. nechany u stojanu na chodbe. chodba v prizemi', 'Chodba v přízemí', 50.13001, 14.36986, '2026-10-06', '2026-11-22 13:05:04', NULL),
(11, 1, 5, 2, 'found', 'returned', 'Sluneční brýle ve žlutém pouzdře', 'slunecni-bryle-ve-zlutem-pouzdre', 'Černé sluneční brýle v pevném žlutém pouzdře. Už vráceny majitelce.', 'slunecni bryle ve zlutem pouzdre cerne slunecni bryle v pevnem zlutem pouzdre. uz vraceny majitelce. lavicka pred vchodem', 'Lavička před vchodem', 50.12983, 14.37204, '2026-09-27', '2026-11-22 13:05:04', NULL),
